rss.channel:
    {{ site.Title }}
    {{ site.BaseURL }}
    {{ with site.Params.description }}{{ . }}{{ else }}Recent content on {{ site.Title }}{{ end }}
    {{ site.Language.LanguageCode | default site.Language.Lang }}
    {{ site.Params.contactEmail }} ({{ site.Params.author }})

    {{ $posts := where site.RegularPages "Section" "posts" }}
    {{ range first 24 $posts }}


      {{ .Title }}
      {{ .Permalink }}
      {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
      {{ .Permalink }}

      	{{ $feature := .Resources.GetMatch "feature.*" }}
		{{ if $feature }}
			{{ $xl := $feature.Resize "1920x" }}
			<img src="{{ $xl.Permalink }}" alt="{{ with .Params.feature_image_alt }}{{ . }}{{ else }}{{ .Title }}{{ end }}" />
		{{ end }}
      	{{ .Content | html }}
      	<img src="https://tinylytics.app/pixel/bUqbbv9aC4svM35xagZs.gif?path={{ .RelPermalink | html }}" alt="" style="width:1px;height:1px;border:0;" />


    {{ end }}
